#: The one address the key is ever sent to. Not configurable: there is no
#: flag and no environment variable for it. Tests patch the transport, not
#: this.
API_BASE = "https://api.workpeg.com"

NEXT_PATH = "/v1/dev-functions/next/"
ANSWER_PATH = "/v1/dev-functions/answers/{call}/"
LISTENER_PATH = "/v1/dev-functions/listener/"

KEY_ENV = "WORKPEG_PK"
#: Set only across the re-exec: the inherited pipe's fd that holds the key.
KEY_FD_ENV = "_WORKPEG_KEY_FD"
MAX_KEY = 4096

#: The API waits on at most two calls of one install (13.7's
#: DEV_FUNCTION_CONCURRENCY), so a runner never takes more.
MAX_CONCURRENCY = 2
#: What one answer may weigh: the API refuses more.
MAX_ANSWER_BYTES = 1024 * 1024
#: How long the API keeps a listener's heartbeat without a poll.
HEARTBEAT_S = 15
#: A call's local budget when the API names none, and the most any call
#: gets, whatever its deadline says. The runner polls only while a slot is
#: free, so with both slots busy the next poll waits for a call to end: a
#: call that took a post-save's ~15.75 s would let the heartbeat lapse.
#: The heartbeat less 3 s leaves the answer and the next poll their time.
DEFAULT_CALL_S = 8.0
MAX_CALL_S = float(HEARTBEAT_S - 3)
#: Bounds on the API's ``poll_after_ms``, so a wrong value can neither spin
#: the throttle nor stall the heartbeat.
POLL_MIN_MS = 250
POLL_MAX_MS = 10_000
#: A poll's back-off after a 429, a 503 or no connection: 2 s, doubling,
#: and never as long as the heartbeat, so a listener that waits is still
#: the one listening when it polls again.
BACKOFF_MIN_S = 2.0
BACKOFF_MAX_S = 10.0
#: An answer the API could not take is sent again after these waits,
#: doubling from the first to the second, until the call's deadline.
ANSWER_RETRY_MIN_S = 0.25
ANSWER_RETRY_MAX_S = 0.5

HTTP_TIMEOUT = (5, 15)

