#: A call's id as the API writes one: a UUID, lower case, hyphenated. It is
#: the only part of the answer's URL that comes from the API.
_CALL_ID = re.compile(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-"
                      r"[0-9a-f]{12}")
_SEGMENT = re.compile(r"[A-Za-z0-9_-]+")


class ListenRefused(Exception):
    """The runner will not start, or has stopped. ``str()`` is the line."""


# --- the key ---------------------------------------------------------------

def valid_key(key: str) -> bool:
    """Whether *key* is shaped as a developer key: at most MAX_KEY ASCII
    characters, three base64url segments, the second a JSON object whose
    ``typ`` is ``developer``. Nothing in it is trusted, and the signature
    is the API's to check; this keeps a session token, a peg token or a
    call's own token from ever being sent as a listener's key."""
    if not isinstance(key, str) or not 0 < len(key) <= MAX_KEY \
            or not key.isascii():
        return False
    parts = key.split(".")
    if len(parts) != 3 or not all(_SEGMENT.fullmatch(p) for p in parts):
        return False
    try:
        payload = json.loads(base64.urlsafe_b64decode(
            parts[1] + "=" * (-len(parts[1]) % 4)))
    except (ValueError, binascii.Error, RecursionError):
        return False
    return isinstance(payload, dict) and payload.get("typ") == "developer"


#: The code a re-exec runs: the CLI again, with the same arguments.
CLI_BOOT = "import sys; from workpeg.cli import main; main(sys.argv[1:])"

#: The first line of every re-exec's code, before any other import: ``-c``
#: puts the current folder first on sys.path as ``''``, and a ``.`` on
#: PYTHONPATH names it too, so a ``json.py`` in a peg's folder would be
#: imported in place of the stdlib's. ``sys`` is built in, so importing it
#: reads no folder.
SAFE_PATH = "import sys; sys.path[:] = [p for p in sys.path if p not in ('', '.')]"


def boot_code(boot: str) -> str:
    """*boot*, after :data:`SAFE_PATH`."""
    return f"{SAFE_PATH}\n{boot}"


def _isolation_flags() -> "list[str]":
    """``-P`` (3.11+), which keeps the current folder off sys.path from
    the start; 3.10 has none, and relies on :data:`SAFE_PATH` alone."""
    return ["-P"] if sys.version_info >= (3, 11) else []


def reexec_without_key(argv: "list[str]", environ: Mapping[str, str], *,
                       boot: str = CLI_BOOT) -> None:
    """Replace this process with ``python -c <boot> *argv``, with
    ``WORKPEG_PK`` removed from the environment and the key on an
    inherited pipe. Never returns. Refuses a value that is not a key
    before anything happens."""
    key = environ[KEY_ENV]
    if not valid_key(key):
        raise ListenRefused(BAD_KEY)
    read_end, write_end = os.pipe()
    os.write(write_end, key.encode("ascii"))
    os.close(write_end)
    os.set_inheritable(read_end, True)
    env = {name: value for name, value in environ.items() if name != KEY_ENV}
    env[KEY_FD_ENV] = str(read_end)
    # The person's current folder goes nowhere on sys.path, so a json.py
    # in a peg's folder is not imported in place of the stdlib's: -P where
    # the interpreter has it, and SAFE_PATH first in the code either way.
    flags = _isolation_flags()
    sys.stdout.flush()
    sys.stderr.flush()
    os.execve(sys.executable,
              [sys.executable, *flags, "-c", boot_code(boot), *argv], env)


def take_key(environ: "os._Environ | dict" = os.environ) -> "str | None":
    """The key handed over by :func:`reexec_without_key`, read from its
    pipe and the pipe closed; ``None`` when there was no re-exec."""
    fd_text = environ.pop(KEY_FD_ENV, None)
    if fd_text is None:
        return None
    try:
        fd = int(fd_text)
        chunks = []
        while True:
            chunk = os.read(fd, 8192)
            if not chunk:
                break
            chunks.append(chunk)
        os.close(fd)
        key = b"".join(chunks).decode("ascii")
    except (ValueError, OSError, UnicodeDecodeError):
        raise ListenRefused(BAD_KEY) from None
    if not valid_key(key):
        raise ListenRefused(BAD_KEY)
    return key


# --- the transport ---------------------------------------------------------

def new_session():
    """A ``requests`` session that reads nothing from the environment (no
    proxy, no ``.netrc``, no CA override) and keeps no cookie a server
    sets."""
    import requests

    session = requests.Session()
    session.trust_env = False
    # No redirect is followed because every call passes
    # allow_redirects=False; max_redirects stays as it is, since 0 makes
    # requests raise on the 3xx it was told not to follow.
    session.cookies.set_policy(DefaultCookiePolicy(allowed_domains=[]))
    session.headers.pop("Cookie", None)
    return session


def _problem_type(response) -> str:
    """The last path segment of a problem body's ``type``, ``""`` when
    there is none. Nothing else of the body is read."""
    try:
        body = response.json()
    except ValueError:
        return ""
    value = body.get("type") if isinstance(body, dict) else None
    if not isinstance(value, str):
        return ""
    return value.rstrip("/").rsplit("/", 1)[-1]


# --- running one call ------------------------------------------------------

@dataclass
class Answer:
    status: int
    body: dict
    output: "list[str]"


class ProcessExecutor:
    """``--with process``: one ``python -m workpeg.runtime`` per call."""

    mode = "process"

    def __init__(self, folder: Path, *, debug: bool = False):
        self.folder = folder
        self.debug = debug

    def start(self, say: Callable[[str], None]) -> None:
        pass

    def call(self, envelope: dict, timeout: float) -> Answer:
        from workpeg import function_local

        done = function_local.run_in_child(
            self.folder, envelope, timeout=timeout, debug=self.debug)
        return Answer(done.status, done.body, done.output)

    def stop(self) -> None:
        pass


def docker_available(timeout: float = 10.0) -> bool:
    """Whether a Docker daemon answers, asked once with a bound."""
    from workpeg.run import docker_environment

    if shutil.which("docker") is None:
        return False
    try:
        done = subprocess.run(
            ["docker", "info", "--format", "{{.ServerVersion}}"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            env=docker_environment(os.environ), timeout=timeout)
    except (OSError, subprocess.SubprocessError):
        return False
    return done.returncode == 0


def _free_loopback_port() -> int:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as probe:
        probe.bind(("127.0.0.1", 0))
        return probe.getsockname()[1]


def _fingerprint(folder: Path) -> tuple:
    found = []
    for path in sorted(folder.rglob("*")):
        if "__pycache__" in path.parts or not path.is_file():
            continue
        stat = path.stat()
        found.append((str(path), stat.st_mtime_ns, stat.st_size))
    return tuple(found)


def _old_base_line() -> str:
    """What to build FROM instead of a base whose runtime answers a call
    that carries no invoke key."""
    from workpeg import __version__
    from workpeg.function_base import IMAGE, RELEASE

    if RELEASE.fullmatch(__version__):
        where = f"FROM {IMAGE}:{__version__}, this SDK's own version, or newer"
    else:
        where = (f"FROM {IMAGE} at the first release that has this runner, "
                 "or newer")
    return OLD_BASE.format(where=where)


class DockerExecutor:
    """``--with docker``: the function's own image, on loopback, behind an
    invoke key, rebuilt when a file in its folder changes.

    The image is tagged ``workpeg-listen-<namespace>:dev`` whatever
    ``build.image`` says, so that a dev build never overwrites an image of
    this computer's that has another use, the function base above all."""

    mode = "docker"
    READY_S = 60.0
    BUILD_S = 600
    RUN_S = 120

    def __init__(self, folder: Path, namespace: str, *, session=None):
        self.folder = folder
        self.name = f"workpeg-listen-{namespace}"
        self.image = f"{self.name.lower()}:dev"
        self.invoke_key = secrets.token_hex(32)
        self.port = 0
        self.session = session if session is not None else new_session()
        self._lock = threading.Lock()
        self._seen: tuple = ()
        self._say: Callable[[str], None] = lambda line: None
        # The line of a start that was refused. Once set, the executor is
        # dead: no call is sent to any port again, and each one raises it.
        self._refused: "str | None" = None

    def _docker(self, *args: str, timeout: float = 30) -> None:
        from workpeg.run import docker_environment

        try:
            subprocess.run(["docker", *args], stdout=subprocess.DEVNULL,
                           stderr=subprocess.DEVNULL,
                           env=docker_environment(os.environ),
                           timeout=timeout)
        except (OSError, subprocess.SubprocessError):
            pass

    def _show(self, text: str) -> None:
        """Docker's own output, each line escaped."""
        for line in terminal.shown_lines(text.rstrip("\n")).split("\n"):
            self._say(f"  | {line}")

    def start(self, say: Callable[[str], None]) -> None:
        """Build, run, wait for and probe the container. Any error at any
        step, the first start's or a rebuild's, a refusal or not (a
        half-typed workpeg.json raises JSONDecodeError from the build),
        stops the container and leaves the executor dead, and is raised as
        :class:`ListenRefused` with one escaped line. Ctrl+C is raised as
        it is, after the same stop."""
        self._say = say
        if self._refused is not None:
            raise ListenRefused(self._refused)
        try:
            self._docker("rm", "-f", self.name)
            self.port = _free_loopback_port()
            self._seen = _fingerprint(self.folder)
            self._build()
            self._run()
            self._wait_ready()
            self._probe()
        except BaseException as exc:
            if isinstance(exc, ListenRefused):
                self._refused = str(exc)
            else:
                self._refused = START_FAILED.format(
                    why=shown(f"{type(exc).__name__}: {exc}"))
            self.port = 0
            self.stop()
            if isinstance(exc, ListenRefused) or \
                    not isinstance(exc, Exception):
                raise
            raise ListenRefused(self._refused) from None

    def _build(self) -> None:
        from workpeg.build import build_image

        try:
            build_image(str(self.folder), tag=self.image,
                        timeout=self.BUILD_S, output=self._show)
        except (OSError, RuntimeError) as exc:
            raise ListenRefused(terminal.shown_lines(exc)) from None

    def _run(self) -> None:
        from workpeg.config import load_function_config
        from workpeg.run import docker_environment
        from workpeg.runtime import INVOKE_KEY_ENV

        port = load_function_config(self.folder).get("runtime", {}).get(
            "docker", {}).get("port", 8000)
        if isinstance(port, bool) or not isinstance(port, int) or \
                not 0 < port < 65536:
            raise ListenRefused(BAD_PORT)
        # The key by name only: its value is in docker's environment, which
        # is docker_environment()'s few variables and nothing else, never in
        # an argv that the process list shows.
        env = docker_environment(os.environ)
        env[INVOKE_KEY_ENV] = self.invoke_key
        argv = ["docker", "run", "-d", "--rm", "--name", self.name,
                "-p", f"127.0.0.1:{self.port}:{port}",
                "-e", INVOKE_KEY_ENV, self.image]
        try:
            done = subprocess.run(
                argv, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                text=True, errors="replace", env=env, timeout=self.RUN_S)
        except FileNotFoundError:
            raise ListenRefused(DOCKER_NOT_RUNNING) from None
        except subprocess.TimeoutExpired:
            raise ListenRefused(
                f"docker run did not finish within {self.RUN_S} s.") from None
        if done.returncode != 0:
            self._show(done.stdout or "")
            raise ListenRefused(
                f"The function's container did not start (docker run exit "
                f"{done.returncode}). Check the output above for details.")

    def _probe(self) -> None:
        """``POST /invoke`` with a JSON Content-Type and no invoke key. The
        runtime of a released base refuses it with INVOKE_REFUSED; one
        built FROM an older base answers it, as it would a page open in
        this browser, so its container is stopped."""
        from workpeg.runtime import INVOKE_REFUSED

        try:
            answer = self.session.post(
                f"http://127.0.0.1:{self.port}/invoke", data=b"",
                headers={"Content-Type": "application/json"}, timeout=5,
                allow_redirects=False)
            refused = (answer.status_code == 401
                       and answer.json() == INVOKE_REFUSED)
        except Exception:                             # noqa: BLE001
            refused = False
        if not refused:
            raise ListenRefused(_old_base_line())   # start() stops it

    def _wait_ready(self) -> None:
        deadline = time.monotonic() + self.READY_S
        while time.monotonic() < deadline:
            try:
                answer = self.session.get(
                    f"http://127.0.0.1:{self.port}/healthz", timeout=2,
                    allow_redirects=False)
                if answer.status_code == 200:
                    return
            except Exception:                         # noqa: BLE001
                pass
            time.sleep(0.25)
        raise ListenRefused(
            "The function's container did not answer within "
            f"{self.READY_S:g} s.")

    def _port_for_call(self) -> int:
        """The port to send a call to, after a rebuild when a file
        changed, read under the lock that a rebuild holds. Raises the
        refusal of a start that failed, this call's or an earlier one's,
        so a dead executor sends nothing to any port."""
        with self._lock:
            if self._refused is not None:
                raise ListenRefused(self._refused)
            if _fingerprint(self.folder) != self._seen:
                self._say("A file of the function changed: rebuilding it.")
                self._docker("stop", "-t", "2", self.name)
                self.start(self._say)
            return self.port

    def call(self, envelope: dict, timeout: float) -> Answer:
        import requests

        from workpeg.runtime import INVOKE_KEY_HEADER

        port = self._port_for_call()
        try:
            answer = self.session.post(
                f"http://127.0.0.1:{port}/invoke",
                data=json.dumps(envelope).encode("utf-8"),
                headers={INVOKE_KEY_HEADER: self.invoke_key,
                         "Content-Type": "application/json"},
                timeout=timeout, allow_redirects=False)
        except requests.Timeout:
            return Answer(504, {
                "status": "error", "error_type": "runtime_error",
                "error": f"The function did not answer within {timeout:g} s."},
                [])
        except requests.RequestException:
            return Answer(502, {
                "status": "error", "error_type": "runtime_error",
                "error": "The function's container could not be reached."}, [])
        try:
            body = answer.json()
        except ValueError:
            body = None
        if not isinstance(body, dict):
            return Answer(502, {
                "status": "error", "error_type": "runtime_error",
                "error": "The function's runtime printed no answer."}, [])
        return Answer(answer.status_code, body, [])

    def stop(self) -> None:
        self._docker("stop", "-t", "2", self.name, timeout=20)


# --- the runner -----------------------------------------------------------

def _escape(text: object, secrets_: "tuple[str, ...]") -> str:
    """*text* as a line may print it: every secret replaced, then escaped."""
    value = str(text)
    for secret, mask in secrets_:
        if secret:
            value = value.replace(secret, mask)
    return shown(value)


class Runner:
    """Collects this person's calls for one dev install and runs them."""

    def __init__(self, *, namespace: str, folder: Path, key: str,
                 executor, concurrency: int = MAX_CONCURRENCY,
                 show_payload: bool = False,
                 install_link: str = "",
                 session=None, out: TextIO = None, err: TextIO = None,
                 sleep: "Callable[[float], None] | None" = None):
        from workpeg.ui import devmode

        try:
            refused = devmode.is_refused_label(namespace)
        except devmode.DevModeRefused as refusal:
            raise ListenRefused(str(refusal)) from None
        if refused:
            raise ListenRefused(REFUSED_NAME.format(name=devmode._q(namespace)))
        if not valid_key(key):
            raise ListenRefused(BAD_KEY)
        if not 1 <= concurrency <= MAX_CONCURRENCY:
            raise ListenRefused(CONCURRENCY)
        self.namespace = namespace
        self.folder = folder
        self._key = key
        self.executor = executor
        self.concurrency = concurrency
        self.show_payload = show_payload
        self.install_link = install_link
        self.session = session if session is not None else new_session()
        self.out = out if out is not None else sys.stdout
        self.err = err if err is not None else sys.stderr
        self.listener = secrets.token_hex(16)
        self.exit_line: "str | None" = None
        self.on_stop: Callable[[], None] = lambda: None
        self._stopping = threading.Event()
        # A wait that Ctrl+C or a stop cuts short, unless a test gives its
        # own.
        self.sleep = sleep if sleep is not None else self._stopping.wait
        self._slots = threading.BoundedSemaphore(concurrency)
        self._print_lock = threading.Lock()
        self._workers: "list[threading.Thread]" = []
        self._thread: "threading.Thread | None" = None
        self._takeover = True
        self._announced = False
        self._backoff = 0.0
        self._pending_wait = 0.0

    # -- printing --

    def _secrets(self, token: str = "") -> "tuple[tuple[str, str], ...]":
        return ((self._key, "<key>"), (token, "<token>"))

    def _line(self, text: str, *, stream: "TextIO | None" = None) -> None:
        with self._print_lock:
            print(text, file=stream or self.out, flush=True)

    def say(self, line: str) -> None:
        """One of the SDK's own lines, on stderr."""
        self._line(f"  {line}", stream=self.err)

    # -- the HTTP calls --

    def _headers(self) -> dict:
        return {"Authorization": f"Bearer {self._key}",
                "Content-Type": "application/json",
                "Accept": "application/json"}

    def _send(self, method: str, path: str, body: dict):
        return self.session.request(
            method, API_BASE + path, data=json.dumps(body).encode("utf-8"),
            headers=self._headers(), timeout=HTTP_TIMEOUT,
            allow_redirects=False)

    # -- lifecycle --

    def prepare(self) -> None:
        """Before the first poll: the banner, the process-mode line, and
        the container started (Docker mode)."""
        terminal.warn(BANNER, self.err)
        if self.executor.mode == "process":
            terminal.warn((PROCESS_MODE,), self.err)
        self.executor.start(self.say)

    def first_poll(self) -> None:
        """The first ``next/``, synchronously, so that a refusal ends the
        command before the page is served, and the install and business
        print before the page's own lines. Raises :class:`ListenRefused`."""
        while not self._stopping.is_set():
            if self._poll_once(idle_wait=False):
                return
        if self.exit_line:
            raise ListenRefused(self.exit_line)

    def start(self) -> None:
        self._thread = threading.Thread(target=self._loop, daemon=True,
                                        name="workpeg-listen")
        self._thread.start()

    def stop(self) -> None:
        """Stop polling, tell the API (best effort), wait for calls in
        flight for a moment, and stop the container."""
        self._stopping.set()
        if self._thread is not None and self._thread is not \
                threading.current_thread():
            self._thread.join(timeout=HTTP_TIMEOUT[1] + 1)
        for worker in list(self._workers):
            worker.join(timeout=MAX_CALL_S)
        if self.exit_line != REDIRECT:
            try:
                self._send("DELETE", LISTENER_PATH,
                           {"peg": self.namespace, "listener": self.listener})
            except Exception:                         # noqa: BLE001
                pass
        self.executor.stop()

    def run_forever(self) -> None:
        """``first_poll`` then the loop, in this thread, until stopped."""
        self.first_poll()
        self._loop()

    # -- the loop --

    def _fatal(self, line: str) -> None:
        if self.exit_line is None:
            self.exit_line = line
        self._stopping.set()
        self.on_stop()

    def _loop(self) -> None:
        if self._pending_wait:
            self.sleep(self._pending_wait)
            self._pending_wait = 0.0
        while not self._stopping.is_set():
            self._poll_once()

    def _poll_once(self, *, idle_wait: bool = True) -> bool:
        """One ``next/``. True once the API answered 200. With no call
        waiting it waits ``poll_after_ms``, or, for the first poll, leaves
        that wait to the loop so the page is not held up by it."""
        import requests

        while not self._slots.acquire(timeout=0.5):
            if self._stopping.is_set():
                return False
        handed = False
        try:
            try:
                answer = self._send("POST", NEXT_PATH, {
                    "peg": self.namespace, "listener": self.listener,
                    "takeover": self._takeover})
            except requests.RequestException:
                self._back_off(WAIT_UNREACHABLE)
                return False
            status = answer.status_code
            if 300 <= status < 400:
                self._fatal(REDIRECT)
                return False
            if status in (429, 503):
                self._back_off(WAIT_WORDS.get(
                    _problem_type(answer),
                    WAIT_429 if status == 429 else WAIT_503))
                return False
            if status == 404:
                self._fatal(NOT_OPEN)
                return False
            if status != 200:
                self._fatal(self._refusal(status, answer))
                return False
            try:
                body = answer.json()
            except ValueError:
                body = None
            if not isinstance(body, dict):
                self._fatal(UNEXPECTED.format(status="an unreadable 200"))
                return False
            self._backoff = 0.0
            self._takeover = False
            self._announce(body)
            call = body.get("call")
            if isinstance(call, dict):
                handed = True
                self._hand_over(call)
                return True
            self._say_missed(body)
            if idle_wait:
                self.sleep(self._poll_after(body))
            else:
                self._pending_wait = self._poll_after(body)
            return True
        finally:
            if not handed:
                self._slots.release()

    def _refusal(self, status: int, answer) -> str:
        kind = _problem_type(answer)
        words = PROBLEM_WORDS.get(kind)
        if words is not None:
            return words.format(
                link=self.install_link or "the developer dashboard")
        line = UNEXPECTED.format(status=status)
        return f"{line[:-1]} ({shown(kind)})." if kind else line

    def _back_off(self, why: str) -> None:
        self._backoff = min(BACKOFF_MAX_S,
                            max(BACKOFF_MIN_S, self._backoff * 2))
        self.say(BACKING_OFF.format(why=why, seconds=f"{self._backoff:g}"))
        self.sleep(self._backoff)

    @staticmethod
    def _poll_after(body: dict) -> float:
        value = body.get("poll_after_ms")
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            value = 1000
        return min(POLL_MAX_MS, max(POLL_MIN_MS, value)) / 1000.0

    def _announce(self, body: dict) -> None:
        if self._announced:
            return
        self._announced = True
        install = body.get("install")
        business = body.get("business")
        if isinstance(business, dict):
            name, uuid = business.get("name"), business.get("uuid")
            business_text = (f"{shown(name)} ({shown(uuid)})" if name
                             else shown(uuid))
        else:
            business_text = shown(business)
        self.say(f"Dev install →  {shown(install)}")
        self.say(f"Business    →  {business_text}")
        self.say(RUNS_HERE)

    def _say_missed(self, body: dict) -> None:
        """``missed`` of an empty answer: the API counts each call once, so
        each count is said when it comes."""
        missed = body.get("missed")
        if isinstance(missed, int) and not isinstance(missed, bool) \
                and missed > 0:
            self.say(MISSED_ONE if missed == 1
                     else MISSED.format(count=missed))

    # -- one call --

    def _hand_over(self, call: dict) -> None:
        worker = threading.Thread(target=self._run_call, args=(call,),
                                  daemon=True, name="workpeg-call")
        self._workers = [w for w in self._workers if w.is_alive()]
        self._workers.append(worker)
        worker.start()

    @staticmethod
    def _seconds_left(call: dict) -> "float | None":
        """Seconds before the API stops waiting for *call*, at hand-over;
        ``None`` when it names no deadline."""
        value = call.get("deadline_ms")
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            return None
        if value > 1e11:                 # an epoch in ms, not a duration
            value = value - time.time() * 1000
        return value / 1000.0

    @classmethod
    def _time_left(cls, call: dict) -> float:
        """How long an answer to *call* is worth sending."""
        left = cls._seconds_left(call)
        return DEFAULT_CALL_S if left is None else min(MAX_CALL_S,
                                                       max(0.0, left))

    @classmethod
    def _budget(cls, call: dict) -> float:
        """The function's own time for *call*."""
        left = cls._seconds_left(call)
        if left is None:
            return DEFAULT_CALL_S
        return min(MAX_CALL_S, max(0.5, left - 0.25))

    def _run_call(self, call: dict) -> None:
        try:
            self._run_call_inner(call)
        finally:
            self._slots.release()

    def _run_call_inner(self, call: dict) -> None:
        started = time.monotonic()
        deadline = started + self._time_left(call)
        call_id = call.get("id")
        envelope = call.get("envelope")
        if not (isinstance(call_id, str) and _CALL_ID.fullmatch(call_id)) \
                or not isinstance(envelope, dict):
            self.say("The API handed over a call this SDK cannot read, so it "
                     "was not run.")
            return
        context = envelope.get("context")
        context = context if isinstance(context, dict) else {}
        token = context.get("token")
        token = token if isinstance(token, str) else ""
        masks = self._secrets(token)

        try:
            answer = self.executor.call(envelope, self._budget(call))
        except ListenRefused as refusal:
            # The container could not be (re)started, a rebuild FROM an
            # older base say: the runner stops with the refusal's line, as
            # a refused start does, rather than answer 502 and go on.
            self._fatal(terminal.shown_lines(refusal))
            answer = Answer(502, {
                "status": "error", "error_type": "runtime_error",
                "error": RESTART_REFUSED}, [])
        except Exception as exc:                          # noqa: BLE001
            answer = Answer(502, {
                "status": "error", "error_type": "runtime_error",
                "error": "The runner could not run the function."},
                [f"{type(exc).__name__}: {exc}"])
        body = dict(answer.body)
        trace = body.pop("trace", None)
        if token:
            # The answer can reach the page as the save's error text, so a
            # function that quotes its own token does not hand it on.
            body = json.loads(json.dumps(body).replace(token, "<token>"))
        status = answer.status
        # The cap is on the request the API reads, as _send serialises it.
        request = {"listener": self.listener, "status": status, "body": body}
        if len(json.dumps(request).encode("utf-8")) > MAX_ANSWER_BYTES:
            status, body = 502, {"status": "error",
                                 "error_type": "runtime_error",
                                 "error": TOO_LARGE}
            request = {"listener": self.listener, "status": status,
                       "body": body}
        elapsed = int((time.monotonic() - started) * 1000)

        self._print_call(call, context, status, elapsed, masks)
        if self.show_payload:
            shown_envelope = json.loads(json.dumps(envelope))
            if isinstance(shown_envelope.get("context"), dict) and \
                    "token" in shown_envelope["context"]:
                shown_envelope["context"]["token"] = "<token>"
            self._line("    payload  " + _escape(
                json.dumps(shown_envelope, sort_keys=True), masks))
        for line in answer.output:
            self._line("    | " + _escape(line, masks))
        if isinstance(trace, str):
            for line in trace.splitlines():
                self._line("    | " + _escape(line, masks))
        if status == 502 and body.get("error") == TOO_LARGE:
            self.say(TOO_LARGE)

        self._post_answer(call_id, request, deadline)

    def _print_call(self, call, context, status, elapsed, masks) -> None:
        table = context.get("table")
        if isinstance(table, dict):
            table = table.get("name") or table.get("uuid")
        row = context.get("row")
        row = row.get("id") if isinstance(row, dict) else "-"
        parts = [call.get("phase"), table, f"row {row}",
                 f"hop {call.get('hop')}", f"{elapsed} ms", str(status)]
        self._line("  " + "  ".join(_escape(part, masks) for part in parts))

    def _post_answer(self, call_id: str, request: dict,
                     deadline: float) -> None:
        """Send the answer; on a 429, a 503 or no connection, send it again
        after a short wait, until the call's deadline has passed."""
        import requests

        wait = ANSWER_RETRY_MIN_S
        while True:
            try:
                answer = self._send(
                    "POST", ANSWER_PATH.format(call=call_id), request)
                why = None if answer.status_code not in (429, 503) else (
                    f"the API answered {answer.status_code}")
            except requests.RequestException:
                why = "Workpeg's API cannot be reached"
            if why is None:
                break
            if self._stopping.is_set() or time.monotonic() + wait > deadline:
                self.say(ANSWER_NOT_SENT.format(call=shown(call_id), why=why))
                return
            self.sleep(wait)
            wait = min(ANSWER_RETRY_MAX_S, wait * 2)
        if answer.status_code in (200, 204):
            return
        if 300 <= answer.status_code < 400:
            self._fatal(REDIRECT)
        elif answer.status_code == 404:
            self.say(ANSWER_GONE.format(call=shown(call_id)))
        else:
            self.say(f"The API answered {answer.status_code} to the answer "
                     f"of call {shown(call_id)}.")


def make_executor(mode: str, folder: Path, namespace: str, *,
                  debug: bool = False, session=None):
    """The executor for *mode*, after the checks that refuse without
    running anything."""
    if debug and mode != "process":
        raise ListenRefused(DEBUG_NEEDS_PROCESS)
    if mode == "process":
        return ProcessExecutor(folder, debug=debug)
    if not docker_available():
        raise ListenRefused(DOCKER_NOT_RUNNING)
    return DockerExecutor(folder, namespace, session=session)
